testo:
{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run():
	var spawn_position := Vector2(0, 0)
	var checkpoint_pos := Vector2(200, -50)
	spawn_position = checkpoint_pos
	return spawn_position
",
   "domanda": "Quanto vale `spawn_position` alla fine?",
   "spiegazione": "`spawn_position` viene sovrascritta con il valore di `checkpoint_pos`, diventando `Vector2(200, -50)`."
  },
  {
   "codice": "extends RefCounted


func run():
	var is_dead: bool = true
	var health: int = 0
	var max_health: int = 3
	if is_dead:
		health = max_health
		is_dead = false
	return health
",
   "domanda": "Quanto vale `health` alla fine?",
   "spiegazione": "Visto che `is_dead` è vero, il blocco `if` viene eseguito: `health` viene reimpostato al valore massimo (`max_health`, cioè 3) e `is_dead` torna falso."
  },
  {
   "codice": "extends RefCounted


func run():
	var velocity := Vector2(400, 800)
	velocity = Vector2.ZERO
	return velocity
",
   "domanda": "Quanto vale `velocity` dopo l'assegnazione?",
   "spiegazione": "Assegnare `Vector2.ZERO` azzera sia la componente orizzontale che quella verticale, utile alla rinascita per impedire al personaggio di mantenere la velocità precedente."
  },
  {
   "codice": "extends RefCounted


func run():
	var player_y: float = 650.0
	var kill_zone_y: float = 600.0
	var is_falling_into_void: bool = player_y > kill_zone_y
	return is_falling_into_void
",
   "domanda": "Cosa restituisce `run()`?",
   "spiegazione": "`player_y` (650.0) è maggiore di `kill_zone_y` (600.0), quindi la condizione restituisce `true`. Il personaggio ha superato il limite inferiore del livello."
  },
  {
   "codice": "extends RefCounted


func run():
	var spawn_position := Vector2(0, 0)
	var active_flag_2 := false
	var active_flag_1 := true
	if active_flag_2:
		spawn_position = Vector2(100, 0)
	elif active_flag_1:
		spawn_position = Vector2(50, 0)
	return spawn_position
",
   "domanda": "Quanto vale `spawn_position` alla fine?",
   "spiegazione": "`active_flag_2` è falso, quindi il primo blocco viene saltato. Si passa a `elif active_flag_1`, che è vero: `spawn_position` diventa `Vector2(50, 0)`."
  }
 ]
}
